import { Avatar, Badge, Box, Grid, IconButton, Typography } from "@mui/material";
import { ForegroundBox } from "../styled_comp/StyledDiv";
import { useEffect, useState } from "react";
import { userApi } from "../../api/services/user";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import { orange, red, cyan } from "@mui/material/colors";
import { useAuth } from "../../hooks/useAuth";
import { todoApi } from "../../api/services/TodoList";
import { useNavigate } from "react-router-dom";
import ShareEleBox from "./ShareEleBox";
import WannabeLikeBtn from "./WannabeLikeBtn";
import { BsFire } from "react-icons/bs";
import styled from "styled-components";
import { getAssetUrl } from "../../api/url";


const ShowTop3List = ({ e, setIsChange, liking, like, unlike , ranking}) => {
    const token = localStorage.getItem("token");
    const navigate = useNavigate();
    const offset = new Date().getTimezoneOffset() * 60000;
    const currentDate = new Date(Date.now() - offset)
        .toISOString()
        .slice(0, 10);
    localStorage.setItem("date", currentDate);
    const [isRecommend, setIsRecommend] = useState();
    const { loginUser, logout, getUserIdByToken, goToErrPage } = useAuth();
    const [exercise, setExercise] = useState();
    const [breakfast, setBreakfast] = useState();
    const [lunch, setLunch] = useState();
    const [dinner, setDinner] = useState();
    const [userImg, setUserImg] = useState("");
    const [loginUserId, setLoginUserId] = useState();
    const [userProfile, setUserProfile] = useState(null);


    const getUploadUser = async () => {
        const userId = e.Users[0].id;
        const res = await userApi.getUser(userId, token);
        setUserProfile(res.payload);
    };

    const uploadUserId = userProfile?.id;
    const getUserInfo = async () => {
        const userId = await getUserIdByToken();
        setLoginUserId(userId);
    };
    const getTodoEle = async () => {
        try {
            const res = await todoApi.getEle(e.id, token);
            const breakfast = res.payload.filter((e) => e?.order == 1);
            const lunch = res.payload.filter((e) => e?.order == 2);
            const dinner = res.payload.filter((e) => e?.order == 3);
            const exercise = res.payload.filter((e) => e?.order == 4);
            setExercise(exercise);
            setBreakfast(breakfast);
            setLunch(lunch);
            setDinner(dinner);
        } catch (err) {
            goToErrPage(err, () => navigate("/err"));
        }
    };

    const onModifyComments = () => {
        localStorage.setItem("date", e.date);
        setIsChange((prev) => !prev);
        navigate("/todolist/share");
    };
    const onDeleteShare = async () => {
        try {
            await todoApi.modifyListShare(e.id, token);
            await todoApi.deleteShareComment(e.Share_comments[0]?.id, token);
            setIsChange((prev) => !prev);
        } catch (err) {
            goToErrPage(err, () => navigate("/err"));
        }
    };
    const getisRecommend = () => {
        const result = e.ListRecommend?.some(
            (user) => user.id == loginUserId
        );
        setIsRecommend(result);
    };
    const onSetRecommend = async (id) => {
        try {
            const res = await todoApi.todoListRecommend(id, token);
            setIsRecommend(true);
        } catch (err) {
            goToErrPage(err, () => navigate("/err"));
        }
    };
    const onSetUnrecommend = async (id) => {
        try {
            const res = await todoApi.todoListUnrecommend(id, token);
            setIsRecommend(false);
        } catch (err) {
            goToErrPage(err, () => navigate("/err"));
        }
    };

    const onSetRecommendCount = async () => {
        try {
            const count = e?.ListRecommend?.length;
            const id = e?.id;
            const res = await todoApi.modiftyListRecommendCount(
                id,
                { count },
                token
            );
        } catch (err) {
            goToErrPage(err, () => navigate("/err"));
        }
    };


    useEffect(() => {
        getUserInfo();
        getUploadUser();
    }, [loginUser]);

    useEffect(() => {
        if (userProfile) {
            const ud = userProfile.UserDetail;
            const lastProfile = ud.length;
            setUserImg(ud[lastProfile - 1]?.img);
        }
    }, [userProfile]);

    useEffect(() => {
        getTodoEle();
        onSetRecommendCount();
        setIsChange((prev) => !prev);
    }, [isRecommend]);

    useEffect(() => {
        getisRecommend();
    }, [loginUserId]);

    // 아직 loginUser, userProfile을 못 가져온 상태처리
    if (!loginUser || !userProfile) {
        return <div>Loading...</div>;
    }

    return (
        <ForegroundBox
            style={{
                backgroundColor: "#ffffff99",
                width: "100%",
                flexDirection: "column",
                marginTop: "5px",
            }}
        >
            <Grid container spacing={0} alignItems="center">
                {userImg && (
                    <Grid item xs={3}>
                        <Badge
                            overlap="circular"
                            anchorOrigin={{
                                vertical: "bottom",
                                horizontal: "right",
                            }}
                            badgeContent={
                                <SmallAvatar
                                    alt="Remy Sharp"
                                    src={ranking}
                                />
                            }
                        >
                            <Avatar
                                src={getAssetUrl(userImg)}
                                
                                alt={"img"}
                                style={{
                                    borderRadius: "240px",
                                    objectFit: "cover",
                                    width:"60px",
                                    height:"60px",
                                    backgroundColor: "white",
                                }}
                            />
                        </Badge>
                    </Grid>
                )}
                <Grid item xs={7}>
                    <Typography variant="h5">
                        {userProfile?.user_name}
                    </Typography>
                </Grid>

                {loginUserId === uploadUserId ? (
                    <>
                        <Grid item xs={1}>
                            <IconButton
                                sx={{ margin: "0", padding: "0" }}
                                onClick={() => onModifyComments()}
                            >
                                <EditIcon
                                    fontSize="small"
                                    sx={{ color: orange[400] }}
                                />
                            </IconButton>
                        </Grid>
                        <Grid item xs={1}>
                            <IconButton
                                sx={{ margin: "0", padding: "0" }}
                                onClick={() => onDeleteShare()}
                            >
                                <DeleteIcon
                                    fontSize="small"
                                    sx={{ color: red[400] }}
                                />
                            </IconButton>
                        </Grid>
                    </>
                ) : (
                    <>
                        <Grid item xs={1}>
                            {isRecommend ? (
                                <IconButton
                                    sx={{ margin: "0", padding: "0" }}
                                    onClick={() => onSetUnrecommend(e.id)}
                                >
                                    <BsFire color="coral" />
                                </IconButton>
                            ) : (
                                <IconButton
                                    sx={{ margin: "0", padding: "0" }}
                                    onClick={() => onSetRecommend(e.id)}
                                >
                                    <BsFire />
                                </IconButton>
                            )}
                        </Grid>
                        <Grid item xs={1}>
                            {liking && uploadUserId && (
                                <WannabeLikeBtn
                                    alreadyliked={liking}
                                    like_id={uploadUserId}
                                    like={like}
                                    unlike={unlike}
                                />
                            )}
                        </Grid>
                    </>
                )}
            </Grid>
            {exercise?.length ? (
                <ShareEleBox elements={exercise}>운동</ShareEleBox>
            ) : (
                false
            )}
            {breakfast?.length ? (
                <ShareEleBox elements={breakfast}>아침</ShareEleBox>
            ) : (
                false
            )}
            {lunch?.length ? (
                <ShareEleBox elements={lunch}>점심</ShareEleBox>
            ) : (
                false
            )}
            {dinner?.length ? (
                <ShareEleBox elements={dinner}>저녁</ShareEleBox>
            ) : (
                false
            )}
            <ForegroundBox>{e.Share_comments[0]?.comment}</ForegroundBox>
        </ForegroundBox>
    );
};
const SmallAvatar = styled(Avatar)(() => ({
    width: 40,
    height: 40,
}));

export default ShowTop3List;
